svg.script:
window.addEventListener('load', function () {
  var host = document.getElementById('host');
  fetch(new URL('index.html?build=network-recovery-v1', location.href).href, { cache: 'no-store', credentials: 'omit' })
    .then(function (response) {
      if (!response.ok) throw new Error('Launcher response ' + response.status);
      return response.text();
    })
    .then(function (source) {
      var frame = document.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');
      frame.setAttribute('id', 'neo-os');
      frame.setAttribute('title', 'NEO OS');
      frame.setAttribute('allow', 'autoplay; picture-in-picture; clipboard-read; clipboard-write; fullscreen; gamepad');
      frame.setAttribute('allowfullscreen', 'true');
      frame.setAttribute('style', 'position:fixed;inset:0;width:100%;height:100%;border:0;background:#050505');
      frame.setAttribute('srcdoc', source);
      host.textContent = '';
      host.appendChild(frame);
    })
    .catch(function () { host.textContent = 'NEO OS could not load. Refresh to try again.'; });
});
